module Prob_8_26 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);	// Default configuration: 5-bit datapath  parameter				dp_width = 5; 		// Set to width of datapath  output 	[2*dp_width - 1: 0] 	Product;  output							Ready;  input 		[dp_width - 1: 0] 	Multiplicand, Multiplier;  input 							Start, clock, reset_b;  parameter 						BC_size = 	3;		// Size of bit counter  parameter						S_idle =	2'b01, 		// one-hot code   S_add_shift = 	2'b10;		          reg	[2: 0]					state, next_state;  reg	[dp_width - 1: 0]		A, B, Q;				// Sized for datapath  reg 							C;  reg	[BC_size -1: 0]		P;  reg				Load_regs, Decr_P, Add_shift, Shift;  assign			Product = {C, A, Q};  wire				Zero = (P == 0);			// counter is zero  wire				Ready = (state == S_idle);	// controller status// control unit  always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q[0], Zero) begin    next_state = S_idle;    Load_regs = 0;    Decr_P = 0;    Add_shift = 0;    Shift = 0;    case (state)      S_idle:					begin if (Start) next_state = S_add_shift; Load_regs = 1; end      S_add_shift:			begin          Decr_P = 1;          if (Zero) next_state = S_idle;          else begin           next_state = S_add_shift;           if (Q[0]) Add_shift = 1; else Shift = 1;  			 				     end								end      default:				next_state = S_idle;    endcase  end// datapath unit  always @ (posedge clock) begin    if (Load_regs) begin      P <= dp_width;      A <= 0;      C <= 0;      B <= Multiplicand;     Q <= Multiplier;    end    if (Decr_P) P <= P -1;     if (Add_shift) {C, A, Q} <= {C, A+B, Q} >> 1;    if (Shift) {C, A, Q} <= {C, A, Q} >> 1;  endendmodule module t_Prob_8_26;  parameter			dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  wire							Error;   Prob_8_26 M0 (Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #70000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  initial begin #5 Start = 1; end  always @ (posedge Ready) begin    Exp_Value = Multiplier * Multiplicand;  end   assign Error = Ready & (Exp_Value ^ Product);  initial begin    #5 Multiplicand = 0;    Multiplier = 0;    repeat (32) #10 begin Multiplier = Multiplier + 1;      repeat (32) @ (posedge M0.Ready) #5 Multiplicand = Multiplicand + 1;    end  endendmodule